#!/bin/sh
# Build and run the haptics module's host-side tests against a checkout of
# nyx-lib's public headers (NYX_LIB_INCLUDE, default ../nyx-lib/include/public).
#
# Covers the pulse patterns of the timed_output / leds-class vibrator. Nothing
# needs a device or root: a FIFO stands in for the vibrator's sysfs file.
# Extra compiler flags (sanitizers, say) go in CFLAGS.
set -e
here=$(cd "$(dirname "$0")" && pwd)
top=$(cd "$here/../../.." && pwd)
nyxinc=${NYX_LIB_INCLUDE:-$top/../nyx-lib/include/public}
build=${BUILD_DIR:-/tmp}
# nyx_version.h is generated by nyx-lib's CMake; make one from the template.
mkdir -p "$build/nyxgen/nyx/common"
sed -e 's/@NYX_API_VERSION_MAJOR@/7/' -e 's/@NYX_API_VERSION_MINOR@/0/' \
    "$nyxinc/nyx/common/nyx_version.h.in" > "$build/nyxgen/nyx/common/nyx_version.h"

out=$build/test_haptics
# shellcheck disable=SC2046,SC2086  # pkg-config output and CFLAGS are flag lists
${CC:-cc} -std=gnu99 -Wall -Wextra -Wno-unused-function -Wno-unused-parameter -DTEST_HOST \
    ${CFLAGS:-} \
    -I"$top/src/system/tests/stubs" -I"$build/nyxgen" -I"$nyxinc" -I"$top/include/internal" \
    $(pkg-config --cflags glib-2.0 libudev) \
    "$here/test_haptics.c" $(pkg-config --libs glib-2.0 libudev) -o "$out"
echo "== test_haptics"
exec "$out" "$@"
